@startuml

class Aircraft {
  + Name : string
  + Type : string
  + YearOfManufacture : int
  + NextInspectionDate : date
}

class PassengerAircraft extends Aircraft {
  + NumberOfSeats : int
}

class SeatCategory {
  + Designation : string
  + OffersEntertainment : boolean
  + SeatCount : int
}

class Flight {
  + FlightNumber : string
  + Date : date
}

class Passenger {
  + Name : string
  + PassportNumber : string
}

class Ticket {
  + TicketNumber : string
  + Price : float
  + UpgradeDesired : boolean
}

class Airline {
  + Name : string
}

class FlightAttendant {
  + Name : string
  + DateOfEmployment : date
  + IsChiefStewardess : boolean
}

class Pilot {
  + Name : string
  + DateOfEmployment : date
  + License : string
}

class Airport {
  + Name : string
  + Address : string
  + RunwayCount : int
}

class FlightExecution {
  + Date : date
}

Airline "1" -- "*" Aircraft : belongs to
Airline "1" -- "*" FlightAttendant : employs
Airline "1" -- "*" Pilot : employs
Aircraft "1" -- "*" Flight : performs
Aircraft "0..1" -- "1" Airport : home airport
Flight "1" -- "1" Airport : departure airport
Flight "1" -- "1" Airport : destination airport
Flight "1" -- "*" FlightExecution
FlightExecution "1" -- "1" Captain : captain
FlightExecution "1" -- "1..2" Co-pilot : co-pilot
FlightExecution "1" -- "*" FlightAttendant : works on
FlightExecution "1" -- "*" Ticket
Passenger "1" -- "*" Ticket
Ticket "*" -- "1" SeatCategory
Passenger "*" -- "*" Flight

@enduml

